import{z as B,x as s,o as t,c as p,q as o,j as n,D as e,d as r,s as l,S as A,b as E}from"./chunks/framework.C8m1ZpeB.js";const c=JSON.parse('{"title":"贝叶斯组合与参数不确定","description":"","frontmatter":{"title":"贝叶斯组合与参数不确定","date":"2026-09-08T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/bayesian-portfolio.md","filePath":"quant/bayesian-portfolio.md","lastUpdated":1791063341000}'),m={name:"quant/bayesian-portfolio.md"};function d(u,a,D,C,h,f){const i=s("Mermaid");return t(),p("div",null,[a[2]||(a[2]=o('<h1 id="贝叶斯组合与参数不确定" tabindex="-1">贝叶斯组合与参数不确定 <a class="header-anchor" href="#贝叶斯组合与参数不确定" aria-label="Permalink to &quot;贝叶斯组合与参数不确定&quot;">​</a></h1><div class="epigraph"><p>未知的 $\\mu$ 应积分掉，而不是用点估计塞进 Merton 公式；后验越散，有效风险厌恶越高，仓位越收缩。</p><footer>—— 对照 Jorion 对 Bayes–Stein 估计的组合应用；Black–Litterman 的均衡先验</footer></div><p><a href="/quant/garleanu-pedersen">上一课</a>在二次冲击下给出向平滑瞄准点的部分调整，瞄准点含未来信号预期，\\(\\Lambda\\) 必须来自执行模型。缺口是目标本身：GP 把 \\(\\pi^\\ast\\) 当已知再谈怎么交易，样本均值当 \\(\\mu\\) 会在历史运气最好的资产上杠杆。本课钉贝叶斯组合：对 \\(\\mu\\)（及 \\(\\Sigma\\)）求后验，决策最大化后验期望效用，权重向先验收缩。不重讲部分调整增益。主干装置见 <a href="/quant/black-litterman">Black–Litterman</a> 与 <a href="/quant/cov-shrinkage">收缩</a>；后课稳健优化默认已经分清后验平均与最坏情形。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>GP 的瞄准点把 \\(\\mu\\) 当已知；样本均值当 \\(\\mu\\)，Markowitz/Merton 会在历史运气最好的资产上杠杆。贝叶斯：给定先验与样本，对 \\(\\mu\\)（及 \\(\\Sigma\\)）求后验，决策是最大化后验期望效用，或等价地对后验预测分布做 Markowitz。结果通常是：权重向先验（常取均衡市值或 BL 均衡）收缩，有效 \\(\\gamma\\) 变大。问题是把「我们很不确定 \\(\\mu\\)」写成先验方差，而不是写成口头谨慎然后仍用点估计下单。</p><p>预测分布的方差 \\(=\\) 残差方差 \\(+\\) 参数不确定。短样本、高维时第二项主导，最优仓接近无风险或接近均衡，这是特征。</p><p><span class="marginnote">术语翻译：后验预测分布就是「把参数的所有可能取值按后验概率加权，再看明天的收益是什么分布」——参数不再是一个数，而是一团云；预测是把云里每个世界各模拟一遍再混在一起。它的方差比「用点估计算出的方差」多出一块，多出的那块就是参数不确定。</span></p><h3 id="与-bl-的分工" tabindex="-1">与 BL 的分工 <a class="header-anchor" href="#与-bl-的分工" aria-label="Permalink to &quot;与 BL 的分工&quot;">​</a></h3><p>BL 用均衡 \\(\\pi\\) 当先验均值，观点当似然。本课强调：即使没有观点，仅参数不确定也要求收缩。有观点时，观点的置信就是先验精度。不要既用 BL 又用另一套「再保守 50%」的随意分数，除非那 50% 来自后验计算。</p><p><span class="marginnote">对数效用对参数不确定特别脆：Kelly 课已说满 Kelly 在 \\(\\mu\\) 高估时破产风险升。贝叶斯 Kelly 自然分数化。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>先验：\\(\\mu\\) 向均衡或零超额（风险平价精神）；\\(\\Sigma\\) Inverse-Wishart 或因子。后验预测代入二次效用得 \\(\\pi\\)。高维用经验贝叶斯估计先验方差，避免拍 \\(\\tau\\)。对照：点估计 Markowitz vs 后验政策的样本外，对象是扣费 IR 与换手，不是样本内前沿。</p><p>动态：参数后验随数据更新，政策应慢，避免把噪声当新观点——与校准隔日罚同构。</p><p>后验随数据滚动的回路（政策慢、噪声被后验自然滤掉）：</p>',14)),(t(),n(A,null,{default:e(()=>[l(i,{id:"mermaid-40",class:"mermaid",graph:"flowchart%20LR%0A%20%20D%5B%22%E6%96%B0%E6%A0%B7%E6%9C%AC%E5%88%B0%E8%BE%BE%22%5D%20--%3E%20P%5B%22%E6%9B%B4%E6%96%B0%20mu%20%E4%B8%8E%20Sigma%20%E5%90%8E%E9%AA%8C%22%5D%0A%20%20P%20--%3E%20F%5B%22%E5%90%8E%E9%AA%8C%E9%A2%84%E6%B5%8B%E5%88%86%E5%B8%83%22%5D%0A%20%20F%20--%3E%20T%5B%22%E7%9B%AE%E6%A0%87%E4%BB%93%3A%20%E6%9C%9F%E6%9C%9B%E6%95%88%E7%94%A8%E6%9C%80%E4%BC%98%22%5D%0A%20%20T%20--%3E%20A%5B%22%E5%8F%AA%E5%90%91%E7%9B%AE%E6%A0%87%E8%B5%B0%E4%B8%80%E5%B0%8F%E6%AD%A5%22%5D%0A%20%20A%20--%3E%20N%7B%22%E5%90%8E%E9%AA%8C%E5%8A%A8%E5%BE%97%E5%A4%9A%E4%B8%8D%E5%A4%9A%3F%22%7D%0A%20%20N%20--%3E%7C%22%E5%87%A0%E4%B9%8E%E6%B2%A1%E5%8A%A8%3A%20%E5%A4%9A%E5%8D%8A%E6%98%AF%E5%99%AA%E5%A3%B0%22%7C%20S%5B%22%E4%BB%93%E4%BD%8D%E5%87%A0%E4%B9%8E%E4%B8%8D%E5%8F%98%22%5D%0A%20%20N%20--%3E%7C%22%E7%A1%AE%E5%AE%9E%E7%A7%BB%E5%8A%A8%22%7C%20M%5B%22%E7%BC%93%E6%85%A2%E5%86%8D%E5%B9%B3%E8%A1%A1%22%5D%0A%20%20S%20--%3E%20D2%5B%22%E7%AD%89%E5%BE%85%E4%B8%8B%E4%B8%80%E6%89%B9%E6%95%B0%E6%8D%AE%22%5D%0A%20%20M%20--%3E%20D2%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[r(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E("p",null,[E("span",{class:"marginnote"},"数字实例：某资产样本年化超额 12%，但 5 年样本均值的估计标准误约 \\(20\\%/\\sqrt{5}\\approx 9\\%\\)（方差 81）；先验取均衡均值 5%、标准差 5%（方差 25）。按精度加权，后验均值 \\(\\approx(12/81+5/25)/(1/81+1/25)\\approx 6.6\\%\\)——样本只被信了约四分之一。点估计把 12% 全喂给 Markowitz，贝叶斯只喂 6.6%。")],-1)),a[4]||(a[4]=E("h2",{id:"机制",tabindex:"-1"},[r("机制 "),E("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=E("p",null,"积分 \\(\\mu\\) 等于在效用里加一项对估计误差的厌恶。仓位下降、分散上升（不太敢集中押注历史赢家）。这与下一课稳健优化的最坏 \\(\\mu\\) 集合是两条路：贝叶斯对后验加权平均，稳健对集合取 min。前者需要先验，后者需要不确定集。",-1)),a[6]||(a[6]=E("p",null,[E("span",{class:"marginnote"},"直觉类比：先验收缩像「新同事主张 vs 团队共识」——样本是一位新同事的强烈观点，均衡先验是整个团队多年的共识；数据越多、越一致，新同事话语权越大。贝叶斯做的就是把话语权按「证据精度 ÷（证据精度+先验精度）」分配，而不是全听新来的。")],-1)),(t(),n(A,null,{default:e(()=>[l(i,{id:"mermaid-53",class:"mermaid",graph:"flowchart%20TD%0A%20%20Prior%5B%22%E5%85%88%E9%AA%8C%20%E5%9D%87%E8%A1%A1%E6%88%96%20BL%22%5D%20--%3E%20Post%5B%22%E5%90%8E%E9%AA%8C%E9%A2%84%E6%B5%8B%E5%88%86%E5%B8%83%22%5D%0A%20%20Data%5B%22%E6%A0%B7%E6%9C%AC%22%5D%20--%3E%20Post%0A%20%20Post%20--%3E%20Pi%5B%22%E6%9C%9F%E6%9C%9B%E6%95%88%E7%94%A8%E6%9C%80%E4%BC%98%E4%BB%93%20%E8%87%AA%E5%8A%A8%E6%94%B6%E7%BC%A9%22%5D%0A%20%20Point%5B%22%E7%82%B9%E4%BC%B0%E8%AE%A1%20%CE%BC%22%5D%20--%3E%20Expl%5B%22%E6%9D%83%E9%87%8D%E7%88%86%E7%82%B8%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[r(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=o('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>先验错了（均衡本身是错的模型）会把所有人拉向错误基准。稳健课处理先验也不信的情况。计算：全贝叶斯 MCMC 对日频再平衡太重，实务用共轭或 BL 闭式。不要把贝叶斯当成「可以用更短窗口」的许可证——短窗口让后验更散，仓位应更小。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>对参数积分后，仓位收缩、有效风险厌恶上升；这是政策，不只是估计技巧。</li><li>BL 是带均衡先验的实现；不要叠加无来源的再打折。</li><li>与稳健优化不同：平均后验 vs 最坏集合。</li><li>出处：Jorion, <em>Journal of Financial and Quantitative Analysis</em>, 1986（Bayes–Stein）；Black and Litterman, 1992。</li></ul>',4))])}const P=B(m,[["render",d]]);export{c as __pageData,P as default};
